-- 234 (17/11/2026, lô 55): « DELF B1 · Đề 3 », phần ĐỌC theo khung đề B1 format mới: Đọc 1 là bảng OUI/NON 16 ô (8 điểm, câu cũ thừa bị xoá), Đọc 2 chia lại điểm (17 điểm).
-- Sinh bởi scripts/nhap/lo55_kho.mjs --cap B1 --de 3. Sửa thẳng, giữ id bài và id câu (cập nhật theo ord). Chạy lại an toàn.
-- lo18mv42gok004n
update public.exercises set consigne = '<p>Vous travaillez à plein temps et vous voulez suivre un cours pour vous détendre et apprendre quelque chose de nouveau. Vous choisissez le cours en fonction des critères suivants :</p><p>• cours le soir ou le week-end ;<br>• moins de 100 € au total ;<br>• petit groupe (10 personnes maximum) ;<br>• possibilité d''essayer avant de s''inscrire.</p><p>Vous comparez ces quatre annonces. Pour chaque annonce, cochez (☒) OUI si cela correspond au critère ou NON si cela ne correspond pas.</p>', reading_text = null where id = 'lo18mv42gok004n';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'tableau', 'Pour chaque annonce, cochez OUI ou NON.', '{"colonnes":[{"id":"lo18mv42gok004nc1","titre":"Atelier de photographie","texte":"<p>Envie de réussir enfin vos photos ? Notre atelier vous apprend à maîtriser la lumière et le cadrage avec votre propre appareil. Les séances ont lieu le mardi de 19 h à 21 h, après le travail. Le cycle de dix séances coûte 120 €, matériel non compris. Pour que chacun puisse poser ses questions, nous accueillons huit participants au maximum. Attention : l''inscription se fait pour le cycle complet, sans séance de découverte.</p>"},{"id":"lo18mv42gok004nc2","titre":"Cours de cuisine du monde","texte":"<p>Chaque mois, un pays à l''honneur : le Maroc en septembre, le Japon en octobre. Le cours a lieu le samedi matin, de 9 h 30 à midi, dans la cuisine de la maison de quartier. Vous cuisinez dans des groupes de douze personnes et vous repartez avec vos plats. Prix : 25 € la séance, ou 90 € pour les quatre séances du trimestre. La première séance peut être réservée seule : si elle ne vous plaît pas, vous ne vous engagez pas pour la suite.</p>"},{"id":"lo18mv42gok004nc3","titre":"Espagnol pour débutants","texte":"<p>Apprenez l''espagnol en douceur avec une professeure native. Les cours se déroulent en ligne le lundi et le jeudi, de 12 h 15 à 13 h, pendant la pause-déjeuner. Les classes réunissent cinq élèves au maximum, ce qui permet de beaucoup parler. Le trimestre coûte 85 €. Un premier cours gratuit est proposé à toute personne qui le souhaite, sans obligation de s''inscrire ensuite.</p>"},{"id":"lo18mv42gok004nc4","titre":"Théâtre d''improvisation","texte":"<p>Vous êtes timide ? Le théâtre d''improvisation est fait pour vous. Rendez-vous le mercredi à 20 h, salle Molière, pour deux heures de jeux et d''exercices. Nos groupes comptent entre quinze et vingt comédiens amateurs, pour que les scènes soient variées. L''adhésion annuelle est de 150 €, payable en trois fois. Venez assister gratuitement à une séance en septembre avant de vous décider !</p>"}],"criteres":[{"id":"lo18mv42gok004nt1","texte":"Horaires"},{"id":"lo18mv42gok004nt2","texte":"Prix"},{"id":"lo18mv42gok004nt3","texte":"Groupe"},{"id":"lo18mv42gok004nt4","texte":"Essai"}]}'::jsonb, '{"answers":{"lo18mv42gok004nt1_lo18mv42gok004nc1":"OUI","lo18mv42gok004nt2_lo18mv42gok004nc1":"NON","lo18mv42gok004nt3_lo18mv42gok004nc1":"OUI","lo18mv42gok004nt4_lo18mv42gok004nc1":"NON","lo18mv42gok004nt1_lo18mv42gok004nc2":"OUI","lo18mv42gok004nt2_lo18mv42gok004nc2":"OUI","lo18mv42gok004nt3_lo18mv42gok004nc2":"NON","lo18mv42gok004nt4_lo18mv42gok004nc2":"OUI","lo18mv42gok004nt1_lo18mv42gok004nc3":"NON","lo18mv42gok004nt2_lo18mv42gok004nc3":"OUI","lo18mv42gok004nt3_lo18mv42gok004nc3":"OUI","lo18mv42gok004nt4_lo18mv42gok004nc3":"OUI","lo18mv42gok004nt1_lo18mv42gok004nc4":"OUI","lo18mv42gok004nt2_lo18mv42gok004nc4":"NON","lo18mv42gok004nt3_lo18mv42gok004nc4":"NON","lo18mv42gok004nt4_lo18mv42gok004nc4":"OUI"}}'::jsonb, 'Photographie: « le mardi de 19 h à 21 h » (OUI), « 120 € » (NON), « huit participants au maximum » (OUI), « sans séance de découverte » (NON). Cuisine: « le samedi matin » (OUI), « 90 € pour les quatre séances » (OUI), « groupes de douze personnes » (NON), « La première séance peut être réservée seule » (OUI). Espagnol: « de 12 h 15 à 13 h, pendant la pause-déjeuner » (NON), « Le trimestre coûte 85 € » (OUI), « cinq élèves au maximum » (OUI), « Un premier cours gratuit » (OUI). Théâtre: « le mercredi à 20 h » (OUI), « 150 € » (NON), « entre quinze et vingt comédiens » (NON), « assister gratuitement à une séance » (OUI).')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo18mv42gok004n' and q.ord = v.ord;
